{"code":"import json, pathlib, collections, re
root=pathlib.Path('bench/logs')
report_files=[p for p in root.rglob('*.json') if p.name.endswith('_report.json') or p.name=='report.json']
entry_key_counts=collections.Counter(); n_entries=0; with_prepost=0; with_closed=0; closed_examples=[]
for p in report_files:
    try: data=json.loads(p.read_text(encoding='utf-8'))
    except Exception: continue
    entries=None
    if isinstance(data,dict):
        reg=data.get('registry')
        if isinstance(reg,dict): entries=reg.get('entries')
    if isinstance(entries,dict):
        for cid,e in entries.items():
            if not isinstance(e,dict): continue
            n_entries+=1
            entry_key_counts.update(e.keys())
            keys=set(e.keys())
            if any('pre' in k.lower() for k in keys) and any('post' in k.lower() for k in keys): with_prepost+=1
            if e.get('status')=='CLOSED':
                with_closed+=1
                if len(closed_examples)<3: closed_examples.append((str(p),cid, sorted(keys), {k:e.get(k) for k in ('status','proposed_fix','source_hash','verified','falsifier_verdict')}))
print('report_files',len(report_files),'registry_entries',n_entries)
print('top entry keys', entry_key_counts.most_common(40))
print('entries with both pre* and post* key names', with_prepost)
print('closed entries', with_closed, 'examples', closed_examples)
# Look for explicit pre/post target hashes anywhere keys
hash_prepost=[]
for p in root.rglob('*.json'):
    try: data=json.loads(p.read_text(encoding='utf-8'))
    except Exception: continue
    def walk(o,path=''):
        if isinstance(o,dict):
            ks=list(o.keys())
            low=' '.join(ks).lower()
            if ('pre' in low or 'before' in low) and ('post' in low or 'after' in low) and ('hash' in low or 'outcome' in low or 'verdict' in low):
                hash_prepost.append((str(p), path, ks[:30]))
                return
            for k,v in o.items():
                if len(hash_prepost)>20: return
                walk(v,path+'/'+str(k))
        elif isinstance(o,list):
            for i,v in enumerate(o[:20]):
                if len(hash_prepost)>20: return
                walk(v,path+f'[{i}]')
    walk(data)
print('explicit schema-ish prepost candidates', len(hash_prepost), hash_prepost[:10])"}

